import unittest
from labels import render_label

class LabelTests(unittest.TestCase):
    def test_normalizes_name(self):
        self.assertEqual(render_label('  Pump ', 3), 'pump=3')

    def test_zero(self):
        self.assertEqual(render_label('Valve', 0), 'valve=0')
